mkitem!{mkimpl!{impl < 'tcx > Visitor < 'tcx > for SingleUseConstsFinder { fn visit_assign (& mut self , place : & Place < 'tcx > , rvalue : & Rvalue < 'tcx > , location : Location) { if let Some (local) = place . as_local () && let Rvalue :: Use (operand) = rvalue && let Operand :: Constant (_) = operand { let locations = & mut self . locations [local] ; if locations . init_loc . is_some () { self . ineligible_locals . insert (local) ; } else { locations . init_loc = Some (location) ; } } else { self . super_assign (place , rvalue , location) ; } } fn visit_operand (& mut self , operand : & Operand < 'tcx > , location : Location) { if let Some (place) = operand . place () && let Some (local) = place . as_local () { let locations = & mut self . locations [local] ; if locations . use_loc . is_some () { self . ineligible_locals . insert (local) ; } else { locations . use_loc = Some (location) ; } } else { self . super_operand (operand , location) ; } } fn visit_statement (& mut self , statement : & Statement < 'tcx > , location : Location) { match & statement . kind { StatementKind :: StorageLive (_) | StatementKind :: StorageDead (_) => { } _ => self . super_statement (statement , location) , } } fn visit_var_debug_info (& mut self , var_debug_info : & VarDebugInfo < 'tcx >) { if let VarDebugInfoContents :: Place (place) = & var_debug_info . value && let Some (local) = place . as_local () { self . locals_in_debug_info . insert (local) ; } else { self . super_var_debug_info (var_debug_info) ; } } fn visit_local (& mut self , local : Local , _context : PlaceContext , _location : Location) { self . ineligible_locals . insert (local) ; } }}}
mkitem!{mkstruct!{struct LocalReplacer < 'tcx > { tcx : TyCtxt < 'tcx > , local : Local , operand : Option < Operand < 'tcx > > , }}}
mkitem!{mkimpl!{impl < 'tcx > MutVisitor < 'tcx > for LocalReplacer < 'tcx > { fn tcx (& self) -> TyCtxt < 'tcx > { self . tcx } fn visit_operand (& mut self , operand : & mut Operand < 'tcx > , _location : Location) { if let Operand :: Copy (place) | Operand :: Move (place) = operand && let Some (local) = place . as_local () && local == self . local { * operand = self . operand . take () . unwrap_or_else (| | { bug ! ("there was a second use of the operand") ; }) ; } } fn visit_var_debug_info (& mut self , var_debug_info : & mut VarDebugInfo < 'tcx >) { if let VarDebugInfoContents :: Place (place) = & var_debug_info . value && let Some (local) = place . as_local () && local == self . local { let const_op = * self . operand . as_ref () . unwrap_or_else (| | { bug ! ("the operand was already stolen") ; }) . constant () . unwrap () ; var_debug_info . value = VarDebugInfoContents :: Const (const_op) ; } } }}}